package main

import (
	"encoding/json"
	"fmt"
	"github.com/caddyserver/caddy/v2"
)

func main() {
	// Test with a numeric module name
	raw := json.RawMessage(`{"name": 123, "foo": "bar"}`)
	moduleName, result, err := caddy.GetModuleNameInline("name", raw)
	if err != nil {
		fmt.Printf("Error with numeric name: %v\n", err)
	} else {
		fmt.Printf("Success with numeric name: %s, config: %s\n", moduleName, result)
	}

	// Test with a boolean module name
	raw = json.RawMessage(`{"name": true, "foo": "bar"}`)
	moduleName, result, err = caddy.GetModuleNameInline("name", raw)
	if err != nil {
		fmt.Printf("Error with boolean name: %v\n", err)
	} else {
		fmt.Printf("Success with boolean name: %s, config: %s\n", moduleName, result)
	}

	// Test with a string module name (should work)
	raw = json.RawMessage(`{"name": "valid_name", "foo": "bar"}`)
	moduleName, result, err = caddy.GetModuleNameInline("name", raw)
	if err != nil {
		fmt.Printf("Error with string name: %v\n", err)
	} else {
		fmt.Printf("Success with string name: %s, config: %s\n", moduleName, result)
	}
}
EOF
